export interface OrderLine {
  slug: string
  name: string
  qty: number
}

/** Order amounts use the same string format as the quote API, e.g. `19.99 USD`. */
export interface OrderSummary {
  id: string
  subtotal: string
  discount: string
  total: string
}

export interface Order extends OrderSummary {
  lines: OrderLine[]
}

import type { CartLine } from '#shared/types/cart'
import type { Order } from '#shared/types/order'
import { randomUUID } from 'node:crypto'
import { findProduct } from '#server/utils/db'
import { computeQuote } from '#server/utils/quote'

/** Orders live in server memory only; they are lost on restart. */
const orders = new Map<string, Order>()

/** Prices the lines with the quote logic, so the stored amounts are what the server charges. */
export function createOrder(lines: CartLine[], code?: string): Order {
  const order: Order = {
    id: randomUUID(),
    ...computeQuote(lines, code),
    lines: lines.map(line => ({
      slug: line.slug,
      name: findProduct(line.slug)?.name ?? line.slug,
      qty: line.qty,
    })),
  }
  orders.set(order.id, order)
  return order
}

export function findOrder(id: string): Order | undefined {
  return orders.get(id)
}

import type { CartLine } from '#shared/types/cart'
import type { OrderSummary } from '#shared/types/order'
import { defineEventHandler, readBody, createError } from 'h3'
import { findProduct } from '#server/utils/db'
import { createOrder } from '#server/utils/orders'

function isCartLine(line: unknown): line is CartLine {
  if (typeof line !== 'object' || line === null)
    return false
  const { slug, qty } = line as Partial<CartLine>
  return typeof slug === 'string' && !!findProduct(slug) && Number.isInteger(qty) && qty! > 0
}

export default defineEventHandler(async (event): Promise<OrderSummary> => {
  const body = await readBody<{ lines?: unknown, code?: unknown }>(event)
  if (!Array.isArray(body?.lines) || body.lines.length === 0 || !body.lines.every(isCartLine))
    throw createError({ statusCode: 400, statusMessage: 'Invalid order lines' })
  const { id, subtotal, discount, total } = createOrder(
    body.lines,
    typeof body.code === 'string' ? body.code : undefined,
  )
  return { id, subtotal, discount, total }
})

import { defineEventHandler, getRouterParam, createError } from 'h3'
import { findOrder } from '#server/utils/orders'

export default defineEventHandler((event) => {
  const order = findOrder(getRouterParam(event, 'id') ?? '')
  if (!order)
    throw createError({ statusCode: 404, statusMessage: 'Order not found' })
  return order
})

